package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.persistence.*;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
/** Live civic route topology and final supplied-project checks, confirmed through the shared OP2 audit. */
public final class BuilderCivicInspection {
 public static final String ROUTES="kingdom_smp:builder/m05",PROJECT="kingdom_smp:builder/m07",FINAL="kingdom_smp:builder/m08";
 private BuilderCivicInspection(){}
 public static boolean building(String id){return PROJECT.equals(id)||FINAL.equals(id);}
 public record Service(String id,List<BlockPos> approaches){public Service{approaches=List.copyOf(approaches);}}
 public static List<Service> services(ServerLevel level){var server=level.getServer();var all=new TreeMap<String,List<BlockPos>>();
  for(var project:ConstructionService.store(server).projects())if(project.phase()==ConstructionStore.Phase.COMPLETE&&!project.npcDead()&&ConstructionService.structureIntact(level,project)){var approaches=new ArrayList<BlockPos>();for(var block:BlueprintRegistry.get(project.blueprint(),project.blueprintVersion()).blocks(project.rotation()))approach(level,project.origin().offset(block.offset()),block.state(),ConstructionService.bounds(project),approaches);all.put("origin:"+project.origin().asLong(),approaches);}
  var hut=BuilderHutSavedData.get(server).hut().orElse(null);if(hut!=null&&hut.phase()==BuilderHutSavedData.Phase.ACTIVE&&!hut.npcDead()&&BuilderHutService.structureIntact(level,hut)){var approaches=new ArrayList<BlockPos>();for(var block:BuilderHutBlueprint.create().placements(hut.rotation()))approach(level,hut.origin().offset(block.offset()),block.state(),new AABB(hut.origin().getX(),hut.origin().getY()-4,hut.origin().getZ(),hut.origin().getX()+BuilderHutBlueprint.create().width(hut.rotation()),hut.origin().getY()+BuilderHutBlueprint.HEIGHT,hut.origin().getZ()+BuilderHutBlueprint.create().depth(hut.rotation())),approaches);all.put("origin:"+hut.origin().asLong(),approaches);}
  return all.entrySet().stream().filter(e->!e.getValue().isEmpty()).map(e->new Service(e.getKey(),e.getValue())).toList();
 }
 private static void approach(ServerLevel level,BlockPos door,BlockState required,AABB footprint,List<BlockPos> out){if(!(required.getBlock() instanceof DoorBlock)||required.getValue(DoorBlock.HALF)!=net.minecraft.world.level.block.state.properties.DoubleBlockHalf.LOWER)return;var facing=required.getValue(DoorBlock.FACING);for(var side:List.of(facing,facing.getOpposite())){var floor=door.relative(side).below();for(int n=0;n<65;n++){if(!level.hasChunkAt(floor)||!clear(level,floor.above())||!clear(level,floor.above(2)))break;if(!footprint.contains(floor.getX()+.5,floor.getY()+.5,floor.getZ()+.5)){out.add(floor);break;}var state=level.getBlockState(floor);if(!state.isCollisionShapeFullBlock(level,floor)&&!material(state))break;floor=floor.relative(side);}}}
 private static boolean clear(ServerLevel level,BlockPos p){var state=level.getBlockState(p);return state.getCollisionShape(level,p).isEmpty()&&state.getFluidState().isEmpty();}
 private static boolean material(BlockState state){return state.is(Blocks.DIRT_PATH)||state.is(Blocks.COBBLESTONE)||state.is(Blocks.STONE_BRICKS)||state.is(BlockTags.PLANKS)||state.getBlock() instanceof StairBlock||state.getBlock() instanceof SlabBlock;}
 /** A connected component touching N different services certifies N-1 connections, not all N choose2pairs. */
 static int connections(Collection<? extends Set<String>> components){var edges=new HashSet<String>();for(var component:components){var services=component.stream().sorted().toList();for(int n=1;n<services.size();n++)edges.add(services.getFirst()+"|"+services.get(n));}return edges.size();}
 public static String routes(ServerPlayer p,BlockPos center){var level=p.serverLevel();var rules=BuilderCivicRules.get(p.server);int radius=rules.radius(),height=rules.height();var services=services(level);if(services.size()<3)throw new IllegalStateException("Visit at least3intact existing kingdom services before reviewing two public route connections");var footprints=ConstructionService.store(p.server).projects().stream().filter(q->q.origin()!=null).map(ConstructionService::bounds).toList();var hut=BuilderHutSavedData.get(p.server).hut().orElse(null);var exclusions=new ArrayList<AABB>(footprints);if(hut!=null){var b=BuilderHutBlueprint.create();var o=hut.origin();exclusions.add(new AABB(o.getX(),o.getY()-4,o.getZ(),o.getX()+b.width(hut.rotation()),o.getY()+BuilderHutBlueprint.HEIGHT,o.getZ()+b.depth(hut.rotation())));}
  var nodes=new TreeMap<Long,String>();var cells=new HashSet<BlockPos>();for(int cx=(center.getX()-radius)>>4;cx<=(center.getX()+radius)>>4;cx++)for(int cz=(center.getZ()-radius)>>4;cz<=(center.getZ()+radius)>>4;cz++){var chunk=level.getChunkSource().getChunkNow(cx,cz);if(chunk==null)continue;for(int x=Math.max(cx*16,center.getX()-radius);x<=Math.min(cx*16+15,center.getX()+radius);x++)for(int z=Math.max(cz*16,center.getZ()-radius);z<=Math.min(cz*16+15,center.getZ()+radius);z++)for(int y=Math.max(level.getMinBuildHeight()+1,center.getY()-height);y<=Math.min(level.getMaxBuildHeight()-3,center.getY()+height);y++){var pos=new BlockPos(x,y,z);var state=chunk.getBlockState(pos);if(!material(state)||!level.getWorldBorder().isWithinBounds(pos)||exclusions.stream().anyMatch(b->b.contains(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5))||!clear(level,pos.above())||!clear(level,pos.above(2))||!level.getBlockState(pos.below()).isFaceSturdy(level,pos.below(),Direction.UP))continue;if(PlacementProtection.check(level,p,pos.below(),pos.above(2))!=null)continue;if(cells.size()>=8192)throw new IllegalStateException("Route inspection exceeds8192loaded path cells; use a smaller configured radius");cells.add(pos);nodes.put(pos.asLong(),state+"|"+level.getBlockState(pos.below())+"|"+level.getBlockState(pos.above())+"|"+level.getBlockState(pos.above(2)));}}
  var remaining=new HashSet<>(cells);var components=new ArrayList<Set<String>>();while(!remaining.isEmpty()){var start=remaining.iterator().next();var queue=new ArrayDeque<BlockPos>();var component=new HashSet<BlockPos>();remaining.remove(start);queue.add(start);while(!queue.isEmpty()){var pos=queue.removeFirst();component.add(pos);for(var side:Direction.Plane.HORIZONTAL)for(int dy=-1;dy<=1;dy++){var next=pos.relative(side).offset(0,dy,0);if(remaining.remove(next))queue.addLast(next);}}var touches=new TreeSet<String>();for(var service:services)if(service.approaches().stream().anyMatch(component::contains))touches.add(service.id());if(touches.size()>1)components.add(touches);}
  int count=connections(components);if(count<rules.connections())throw new IllegalStateException("Inspect "+rules.connections()+" different grounded public road connections between intact existing services; observed="+count+". Roads must be loaded, permitted, supported, clear/dry and outside reward-structure footprints");return "connections="+count+",radius="+radius+",height="+height+",required="+rules.connections()+",routes="+hash(nodes+"|"+services+"|"+components.stream().map(Object::toString).sorted().toList());
 }
 public static String project(ServerPlayer p,BlockPos center){var frame=RetainedBuildingService.inspectCompletedProject(p,"kingdom_smp:builder/m01");var decor=RetainedBuildingService.inspectCompletedProject(p,"kingdom_smp:builder/m02");if(frame.count()<RetainedBuildingRules.get(p.server).goal("kingdom_smp:builder/m01")||decor.count()<RetainedBuildingRules.get(p.server).goal("kingdom_smp:builder/m02"))throw new IllegalStateException("Maintain your actual supplied Master frame and varied decorative masonry with current site permission");var interior=LayeredInteriorInspection.validate(p,center);var fittings=SupplementariesInspection.validate(p,center);return "civic=maintained,native="+frame.count()+"/"+decor.count()+",project="+hash(frame.hash()+"|"+decor.hash()+"|"+interior+"|"+fittings);}
 private static String hash(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8))).substring(0,32);}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
}
